def inst(
    page_id: str,
    page_name: str,
    slug: str,
    target_description: str,
    evidence_rule: str,
    target_aliases: list[str],
    behavior_signals: list[str],
    element_target: str | None = None,
    trigger_action: str | None = None,
    setup: str | None = None,
) -> dict[str, object]:
    return {
        "page_id": page_id,
        "page_name": page_name,
        "slug": slug,
        "target_description": target_description,
        "element_target": element_target or target_description,
        "trigger_action": trigger_action or f"inspect {target_description}",
        "setup": setup,
        "evidence_rule": evidence_rule,
        "target_aliases": target_aliases,
        "behavior_signals": behavior_signals,
    }


def template(
    template_id: str,
    template_name: str,
    issue_family: str,
    site: str,
    pattern_summary: str,
    recognition_rules: list[str],
    boundary_rules: list[str],
    instances: list[dict[str, object]],
) -> dict[str, object]:
    return {
        "template_id": template_id,
        "template_name": template_name,
        "issue_family": issue_family,
        "site": site,
        "pattern_summary": pattern_summary,
        "recognition_rules": recognition_rules,
        "boundary_rules": boundary_rules,
        "instances": instances,
    }


